create table if not exists public.favorites (id bigint generated by default as identity primary key,user_id uuid not null references auth.users(id) on delete cascade,profile_name text not null check (profile_name in ('Christian','Izabelle')),content_key text not null,title text,poster_path text,media_type text,created_at timestamptz not null default now(),unique(user_id,profile_name,content_key));alter table public.favorites enable row level security;create policy "Users can read own favorites" on public.favorites for select using (auth.uid() = user_id);create policy "Users can insert own favorites" on public.favorites for insert with check (auth.uid() = user_id);create policy "Users can delete own favorites" on public.favorites for delete using (auth.uid() = user_id);create policy "Users can update own favorites" on public.favorites for update using (auth.uid() = user_id);